"use strict";

/**
 * SFT: original row-major 256 table and terminal 76+85+95 GP29 slots.
 * Test an additive GF29 keystream generated by an arbitrary short linear
 * recurrence. Berlekamp-Massey uniquely determines the minimum
 * recurrence from known positions 76..255 without guessing keys.
 *
 * Node.js 22+, Windows-compatible, no external dependencies or writes.
 */
const assert = require("node:assert/strict");
const fs = require("node:fs");
const path = require("node:path");
const crypto = require("node:crypto");
const root = path.resolve(__dirname, "..");
const read = name => fs.readFileSync(path.join(root, name), "utf8");
const gp = JSON.parse(read("resources/liber-primus/lp2-corpus.json"));
const table = JSON.parse(read("resources/liber-primus/lp2-grid-256.json"));
const originalBytes = table.pages.flatMap(p => p.bytes);
assert.equal(originalBytes.length, 256);
assert.equal(
  crypto.createHash("sha256").update(Buffer.from(originalBytes)).digest("hex"),
  "3b9b07d9a26e6d55c432d94d2661fdff3c2b348daed06821f2bdb23184a4b290"
);
assert.equal(gp.pages[55].indices.length, 76);
const p56Cipher = gp.pages[56].indices;
const p57Plain = gp.pages[57].indices;
assert.equal(p56Cipher.length, 85);
assert.equal(p57Plain.length, 95);
const mod = x => ((x % 29) + 29) % 29;

/** Solve a nonzero finite-field inverse. @param {number} x */
function inv(x) {
  assert(x > 0 && x < 29);
  for (let i = 1; i < 29; i++) if (x * i % 29 === 1) return i;
  throw Error("nonunit");
}

/** GP inventory tokenization agrees with the 2014 solved-p56 regression. */
const gpTokens = gp.translit.map((text, index) => ({text, index}))
  .sort((a, b) => b.text.length - a.text.length);
function sourceEncode(text) {
  const out = [];
  for (const word of text.split(" ")) {
    for (let i = 0; i < word.length;) {
      const token = gpTokens.find(x => word.startsWith(x.text, i));
      assert(token, "unrepresentable original solved rune");
      out.push(token.index);
      i += token.text.length;
    }
  }
  return out;
}
const p56Plain = sourceEncode("AN END WITHIN THE DEEP WEB THERE EXISTS A PAGE THAT HASHES TO IT IS THE DUTY OF EUERY PILGRIM TO SEEC OUT THIS PAGE");
assert.equal(p56Plain.length, 85);

/** First 85 successive original prime-totient keys with literal-F bypass. */
function primes(count) {
  const a = [];
  for (let n = 2; a.length < count; n++) {
    let prime = true;
    for (let d = 2; d * d <= n; d++) if (n % d === 0) prime = false;
    if (prime) a.push(n);
  }
  return a;
}
const primeKeys = primes(85);
let keyIndex = 0;
const replay56 = p56Plain.map((x, i) => {
  if (i === 56) {
    assert.equal(x, 0, "single native plaintext-F bypass");
    return 0;
  }
  return mod(x + primeKeys[keyIndex++] - 1);
});
assert.equal(keyIndex, 84);
assert.deepEqual(replay56, p56Cipher, "p56 authentic plaintext independently reencrypts");

/**
 * Return the unique minimum homogeneous recurrence for an entire GF29 tape.
 * C[0] == 1, with Σ_{j=0}^L C[j]*s[n-j]=0 for every n>=L.
 * @param {number[]} samples
 * @returns {{degree:number,poly:number[]}}
 */
function berlekampMassey(samples) {
  let C = [1], B = [1], L = 0, m = 1, b = 1;
  for (let n = 0; n < samples.length; n++) {
    let discrepancy = samples[n];
    for (let j = 1; j <= L; j++) {
      discrepancy = mod(discrepancy + (C[j] || 0) * samples[n-j]);
    }
    if (discrepancy === 0) {
      m++;
      continue;
    }
    const before = C.slice();
    const scale = mod(discrepancy * inv(b));
    while (C.length < B.length + m) C.push(0);
    for (let j = 0; j < B.length; j++) {
      C[j+m] = mod(C[j+m] - scale * B[j]);
    }
    if (2 * L <= n) {
      L = n + 1 - L;
      B = before;
      b = discrepancy;
      m = 1;
    } else {
      m++;
    }
  }
  return { degree:L, poly:C.slice(0,L+1) };
}

/**
 * Use first 90 known K steps to predict each held-out step without retuning.
 * @param {number[]} known
 * @param {number[]} poly
 */
function holdout(known, poly) {
  let hits = 0, firstMismatch = null;
  const L = poly.length - 1;
  for (let i = 90; i < known.length; i++) {
    let predicted = 0;
    for (let j = 1; j <= L; j++) {
      predicted -= poly[j] * known[i-j];
    }
    predicted = mod(predicted);
    if (predicted === known[i]) hits++;
    else if (firstMismatch === null) firstMismatch = i;
  }
  return {hits,total:known.length-90,firstMismatch};
}

/**
 * Recover preceding source key runes from a full-rank recurrence known on
 * 76..255. The final lag coefficient must be a unit.
 * @param {number[]} known
 * @param {number[]} poly
 */
function backsolve76(known, poly) {
  const L = poly.length-1;
  assert(L > 0 && L <= 76);
  const recovered = Array(256).fill(null);
  for (let i = 0; i < known.length; i++) recovered[i+76] = known[i];
  const ilast = inv(poly[L]);
  for (let n = 75+L; n >= L; n--) {
    let v = recovered[n];
    for (let j = 1; j < L; j++) v += poly[j] * recovered[n-j];
    recovered[n-L] = mod(-v * ilast);
  }
  assert(recovered.every(Number.isInteger));
  return recovered;
}
const terminalKnown = [...p56Plain,...p57Plain];
const terminalPrinted = [...p56Cipher,...p57Plain];
assert.equal(terminalKnown.length, 180);
assert.equal(terminalPrinted.length, 180);
const originalResidues = originalBytes.map(x => x % 29);

function examine(knownPlain) {
  const knownKey = knownPlain.map((p, j) =>
    mod(originalResidues[j+76] - p));
  const trained = berlekampMassey(knownKey.slice(0,90));
  const complete = berlekampMassey(knownKey);
  return {
    first90Complexity: trained.degree,
    all180Complexity: complete.degree,
    heldout: holdout(knownKey, trained.poly),
    eightOrFewerPossible: complete.degree <= 8
  };
}
const solved = examine(terminalKnown);
const printed = examine(terminalPrinted);
assert.deepEqual([solved.first90Complexity,solved.all180Complexity,
  solved.heldout.hits, solved.heldout.firstMismatch], [45,91,5,90]);
assert.deepEqual([printed.first90Complexity,printed.all180Complexity,
  printed.heldout.hits, printed.heldout.firstMismatch], [46,90,3,90]);
assert(!solved.eightOrFewerPossible && !printed.eightOrFewerPossible);

/**
 * Positive: use exactly 76 hidden native-GP runes from authentic solved
 * p57 as synthetic unknown p55; combine with authentic known p56/p57.
 * Encode all 256 with degree-four nonzero-last-coefficient GF29 LFSR.
 * Recover recurrence *solely* from 180 known trailing symbols, invert
 * it backwards to position zero and recover all 76 planted unknowns.
 */
const plantedPlain = [...p57Plain.slice(0,76),...terminalKnown];
assert.equal(plantedPlain.length, 256);
const selectedPoly = [1,5,8,11,17];
const plantedKey = [7,11,13,17];
for (let i = 4; i < 256; i++) {
  let next = 0;
  for (let j = 1; j <= 4; j++) next -= selectedPoly[j]*plantedKey[i-j];
  plantedKey.push(mod(next));
}
const plantTable = plantedPlain.map((p,i)=>mod(p+plantedKey[i]));
const visible180 = terminalKnown.map((p,j)=>mod(plantTable[j+76]-p));
const learned = berlekampMassey(visible180);
assert.equal(learned.degree, 4);
assert.deepEqual(learned.poly, selectedPoly);
const recoveredKey = backsolve76(visible180,learned.poly);
assert.deepEqual(recoveredKey, plantedKey);
const recoveredHidden = plantTable.slice(0,76).map((v,i)=>mod(v-recoveredKey[i]));
assert.deepEqual(recoveredHidden, plantedPlain.slice(0,76),
  "entire genuine-source GP29 plant recovered by known-only key inversion");
const plantHeldout = holdout(visible180,berlekampMassey(visible180.slice(0,90)).poly);
assert.equal(plantHeldout.hits,90);

const result = {
  status: "bounded negative; no unknown p55 plaintext or authentic LFSR",
  originalTable: "256 source row-major base60 bytes reduced mod29",
  terminalAlignment: "76 hidden p55 followed by 85 p56 and 95 p57",
  originalKnownRunes:180,
  sourceKnownSolvedP56:solved,
  sourceKnownPrintedP56:printed,
  plantedPositive:{
    chosenRecurrence:selectedPoly,
    recoveredRecurrence:learned.poly,
    heldoutKeyPredictions:plantHeldout,
    recoveredAllPlanted76:76
  }
};
if (require.main === module) console.log(JSON.stringify(result,null,2));
module.exports={berlekampMassey, backsolve76};
